    "problem": "앱을 새로 설치한 뒤 구글 클라우드 동기화를 실행하고 기존 노트의 음성 메모를 재생하면, 일시정지 아이콘만 표시된 채 파형과 재생 시간이 00:00에서 전혀 움직이지 않고 오디오가 재생되지 않던 결함 (신규 녹음 음성은 정상 재생됨). 원인: 1) SyncMediaEngine.extractMediaFileNames가 다중 음성 첨부 JSON 배열 문자열을 미파싱하여 'memo_xxx.m4a\",\"durationSec\":16...]'와 같은 깨진 파일명을 추출함으로써 로컬 파일 존재 검사 및 구글 드라이브 업로드/다운로드 파이프라인이 100% 무산됨. 2) ArchiveRestoreEngine.normalizeRestoredMediaUri가 JSON 배열을 인식하지 못하고 /audio/ 이후를 잘라내어 SQLite에 파손된 URI를 저장함. 3) SyncPushEngine/SyncPullEngine이 텍스트 변경이 없는 기존 노트의 누락 미디어 업로드 및 로컬 미존재 미디어 재다운로드를 스킵함. 4) AudioPlayerView가 로드 실패(!status.isLoaded) 시에도 setIsPlaying(true)를 무조건 호출하여 정지 상태에서 일시정지 아이콘으로 굳어버리던 버그 복합 발생.",
    "solution": "1) services/cloudSync/syncMediaEngine.ts: extractMediaFileNames에서 JSON 오디오 배열(starts with '[') 파싱 및 각 첨부파일별 파일명 추출 지원, extractFileNameFromUri 정규식 기반 정밀 파일명 정제(/^[a-zA-Z0-9_\\-\\.]+/) 적용으로 JSON 찌꺼기 100% 제거. 2) services/cloudSync/archiveRestoreEngine.ts: normalizeRestoredMediaUri에 다중 음성 JSON 배열 재귀 정규화 및 기존 손상 URI 자동 치유(Self-Healing) 파이프라인 구축. 3) utils/audioUtils.ts: resolveReliableAudioUri의 안드로이드 크로스 플랫폼 재연결 및 손상 JSON 파편 정제 이식. 4) services/cloudSync/syncPushEngine.ts & syncPullEngine.ts: 텍스트 변경 없는 기존 노트의 미디어 업로드 보정 및 로컬 미디어 누락 노트 자동 재다운로드 리컨실리에이션(Reconciliation) 구축. 5) components/voice/AudioPlayerView.tsx: 로컬 파일 부재 시 구글 드라이브 온디맨드 스트리밍 다운로드 및 status.isLoaded 검증 가드 추가. 6) 94개 스위트 523개 단위 테스트 100% ALL PASS.",
