    "problem": "일정(Schedule) 등록 화면에서 알림 옵션('당일 정시(on_time)', '10분 전(10m_before)', '1시간 전(1h_before)', '커스텀(custom_...)' 등)을 지정하고 저장해도 실제 해당 시간에 OS 푸시 알림이 전혀 오지 않는 치명적 결함 발생. 원인 분석: 1) DDayNotificationHelper.ts의 타이밍 계산 로직이 오직 D-Day 레거시 키(0d_09, 0d_exact, 1h, 1d, 3d, 7d) 6개만 하드코딩 분기 처리되어 있어, 일정 등록 시 저장되는 'on_time', '10m_before', 'custom_...' 키들은 전부 triggerDate가 null로 떨어져 스케줄링이 통째로 스킵됨. 2) Android 8.0+에서 일정 알림을 띄우기 위한 'schedule' 전용 알림 채널(Notification Channel) 부재. 3) 일정 알림 설정 시 알림 권한(POST_NOTIFICATIONS) 사전 요청 트리거 누락. 4) DDayNotificationHelper의 알림 메시지 페이로드가 D-Day 생일/시험 문구 위주로 하드코딩되어 일정 전용 타이틀/본문 부재.",
    "solution": "1) services/ddayNotificationHelper.ts 전면 개편: calculateReminderTriggerDate 신설하여 on_time(시간 지정 시 정시, 종일 시 09:00), 10m_before, 30m_before, 1h_before, 1d_before, 3d, 7d, custom_${num}_${unit}(분/시간/일/주) 전수 계산 완벽 지원. 2) getScheduleReminderNotificationPayload 신설: 일정 전용 감성 푸시 타이틀(📅 [일정] 시작 시간입니다, ⏰ 10분 전입니다 등) 및 시간/메모 요약 본문 생성. 3) Android 일정 전용 고우선순위 알림 채널('schedule', AndroidImportance.HIGH) 신설 및 ensureChannels 사전 보장. 4) QuickScheduleModal.tsx 저장 시 알림 활성화 상태일 경우 notificationService.requestPermissions() 자동 연동하여 권한 미승인 시 OS 허용 팝업 트리거 보장. 5) constants/DDayReminderOptions.ts의 DDayReminderType 및 formatReminderSummaryKo 확장. 6) 전용 단위 테스트 suite (__tests__/services/scheduleNotification.test.ts 10건) 작성 및 동기식 3중 검증 100% PASS (tsc 0건, Jest 98개 스위트 560개 테스트 ALL PASS).",
