    "problem": "홈 화면 워크스페이스 허브 위젯의 메모 목록에 일반 메모가 아닌 캘린더 일정(Schedule)이나 디데이가 섞여 노출되는 결함 발생. 원인 분석: 1) Modo는 SQLite의 단일 notes 테이블에 메모, 음성, 일정(is_schedule: 1), 디데이(d_day_date)를 함께 저장함. 2) stores/notesStore.ts의 syncWidgetFromNotes에서 전체 notes 배열을 단순 slice(0, 10)하여 위젯 서머리로 전달함으로써 최근 등록/수정된 일정이 위젯 메모 목록 1~3번에 그대로 주입됨. 3) iOS AppGroup 동기화(iosWidgetSync.ts) 및 Android 위젯 렌더러(renderSingleWidgetInstance.tsx, widgetTaskHandler.tsx)에서도 일정 필터링 가드가 부재하여 위젯 화면에 일정이 그대로 렌더링됨.",
