    "title": "iOS 홈 화면 시계 위젯 분 단위 실시간 갱신(60분 타임라인 엔진) 구축 및 위젯 모델별 AppGroup 독립 격리 저장(선별적 동기화) 파이프라인 구현",
    "problem": "1) iOS 홈 화면 시계 위젯(스퀘어 시계, 프로 시계)의 시간이 실시간으로 흐르지 않고 스크린샷처럼 멈춰 있거나 과거 시간에 고정되는 현상 발생. 원인 분석: ClockTimelineProvider에서 단 1개의 타임라인 엔트리([entry])만 생성하고 다음 갱신을 30분 뒤(.after(30min))로 예약함에 따라, WidgetKit의 백그라운드 렌더링 특성상 한 번 렌더링된 분(minute)에서 30분간 화면이 멈춤. 또한 SwiftUI 뷰에서 entry.date 대신 Date()를 직접 바인딩하여 타임라인 시점과 불일치 발생. 2) 위젯 스튜디오에서 특정 위젯(예: 캘린더, 포스트잇 등)의 색상이나 테마를 변경하고 [적용] 시, 홈 화면에 이미 설치된 다른 형태의 위젯(예: 시계, 툴바 등)의 색상이 기본값으로 초기화되거나 엉뚱한 값으로 덮어씌워지는 결함 발생. 원인 분석: iosWidgetSync.ts의 syncToAppGroup이 호출될 때마다 8개 위젯 모델 10개 키를 AppGroup UserDefaults에 무조건 일괄 덮어쓰기하여, 수정하지 않은 다른 위젯의 커스텀 설정이 기본값으로 강제 리셋됨.",
    "solution": "1) ClockTimelineProvider 60분 분 단위 실시간 타임라인 구축: targets/widgets 및 ios/ModoWidgets의 ClockTimelineProvider.swift에서 1분 간격의 60개 ClockEntry 시퀀스를 생성하고 타임라인 정책을 .atEnd로 설정하여 시스템 레벨에서 매 분마다 시계가 물 흐르듯 실시간 전환되도록 구현. 2) SwiftUI 뷰 엔트리 날짜 바인딩: ModoSquareClockWidget.swift 및 ModoProClockWidget.swift의 Text(Date(), ...)를 Text(entry.date, ...)로 전환하여 타임라인 스케줄러와 100% 동기화. 3) 위젯 모델별 선별적 격리 저장(Selective Persistence): services/widget/platform/iosWidgetSync.ts의 syncToAppGroup에서 targetModel을 기준으로 변경된 모델의 AppGroup 키만 선별적으로 저장하도록 분리. 캘린더 적용 시 시계/툴바/포스트잇/킵허브의 UserDefaults 데이터를 절대 덮어쓰지 않도록 원천 격리. 메모 갱신(syncAllWidgetsImmediately) 시에도 킵허브 키만 선별 업데이트. 4) 전용 격리 검증 단위 테스트 2건 추가 및 3중 검증 통과 (tsc 0건, Jest 99개 스위트 569개 테스트 100% ALL PASS, lint 0건).",
