    "problem": "1) 홈 화면에 시계 위젯(스퀘어 시계, 프로 시계)을 추가하거나 스튜디오에서 적용할 때, 이전에 추가해둔 워크스페이스 허브(KeepHub) 위젯의 색상이 갑자기 어둡게 변하는 현상 발생. 원인 분석: (1) DynamicIconModule.swift 및 iosWidgetSync.ts에서 특정 위젯 적용 시 WidgetCenter.shared.reloadAllTimelines()를 무차별 호출하여 홈 화면의 모든 위젯 타임라인을 강제 리로드함. (2) KeepHub가 리로드될 때 사용자가 스튜디오에서 직접 적용하지 않은 상태에서는 AppGroup UserDefaults의 @modo_widget_config_keephub가 nil이 되어, ModoKeepHubWidget.swift의 defaultSampleConfig()로 폴백되는데 이 기본값이 theme: 'dark'로 하드코딩되어 검은 슬레이트 색상(#0F172A)으로 변색됨. (3) Swift 코드 내에서 config.theme == 'light'만 라이트로 인식하여 크라프트, 린넨, 세이지, 사쿠라 등 7종 종이 질감 테마 및 시스템 라이트 모드가 어둡게 강제 처리됨. (4) 노트 변경 시 KeepHub 페이로드를 만들 때 기존 AppGroup의 사용자 테마 설정을 보존하지 않고 pKeepHub.theme || 'dark'로 덮어쓰던 결함.",
    "solution": "1) DynamicIconModule.swift 및 expo-dynamic-icon/index.ts에 reloadWidgetTimelines(ofKind: String) 네이티브 모듈 함수 추가하여 WidgetCenter.shared.reloadTimelines(ofKind: ofKind) 타깃 갱신 API 신설. 2) iosWidgetSync.ts에서 targetModel(clock, square_clock, keephub 등)에 매핑된 네이티브 위젯 kind만 선별적으로 리로드하도록 개편하여 시계 위젯 추가/설정 시 KeepHub에 일절 간섭하지 않도록 완전 격리. 3) iosWidgetSync.ts에서 KeepHub 페이로드 생성 시 기존 AppGroup UserDefaults 설정을 사전 조회하여 targetModel이 keephub가 아닐 때(노트 동기화 등) 기존 theme, textColorCustom, photoThemeId, scale, fontFamily를 100% 무손실 보존. 4) targets/widgets 및 ios/ModoWidgets의 ModoKeepHubWidget.swift, ModoKeepHubWideWidget.swift에 @Environment(\\.colorScheme) var colorScheme 추가 및 7종 종이 질감 테마(kraft, parchment, sage, sakura, light, dark, glass) 정품 배경색/카드보더 색상 완벽 구현, defaultSampleConfig()의 theme을 'system'으로 정규화. 5) 단위 테스트 3건 신설 및 동기식 3중 검증 100% ALL PASS (tsc 0건, Jest 99개 스위트 572개 테스트 통과, lint 0건).",
