    "problem": "홈 화면에 추가된 시계 위젯(스퀘어 시계, 프로 시계)을 길게 누르고 [위젯 편집] 진입 시 글꼴 스타일(Font Family)만 노출되고 CRT 색상과 테마 설정이 누락되어 선택할 수 없던 결함 발생. 또한 위젯 인스턴스 설정이 미지정(.unknown) 상태로 남아 전역 공유 저장소를 읽어옴에 따라, 앱 내에서 두 번째 시계 위젯 스타일을 변경하면 첫 번째 위젯의 색상과 테마까지 두 번째 위젯의 설정으로 덮어씌워지는 연쇄 결함 발생. 원인 분석: 1) ModoClockConfiguration.intentdefinition의 INIntentParameters 내 crtColor, theme, fontFamily에 INIntentParameterConfigurable: true 플래그 누락. 2) INIntentParameterCombinations 조합 키가 빈 문자열(\"\")로 누락되어 있고 INIntentParameterCombinationIsPrimary 플래그가 미지정되어, iOS SpringBoard가 파라미터 조합을 인식하지 못하고 마지막 파라미터(Font Family)만 임의 노출함. 3) 이로 인해 인스턴스별 커스텀 값이 .unknown으로 유지되어 앱 내 전역 UserDefaults 값을 읽어와 다른 시계 위젯 간 설정 덮어쓰기 발생.",
    "solution": "1) targets/widgets 및 ios/ModoWidgets의 ModoClockConfiguration.intentdefinition 스키마 정밀 보강: crtColor, theme, fontFamily 3개 파라미터 모두에 INIntentParameterConfigurable: true 및 DisplayPriority(1, 2, 3), Tag(1, 2, 3) 부여. 2) INIntentParameterCombinations에 알파벳 정렬된 고유 조합 키 <key>crtColor,fontFamily,theme</key>를 선언하고 INIntentParameterCombinationIsPrimary: true 및 BackgroundExecution 허용 설정. 3) intentbuilderc 컴파일 및 코드 생성, xcodebuild -scheme ModoWidgets 네이티브 빌드 성공(BUILD SUCCEEDED), tsc 0건, npm test 99 suites 572 tests 100% ALL PASS, ESLint 0건 동기식 4중 검증 완료.",
